/// Presentation identity for one committed turn. Cells, not jewel colors, identify pieces.
/// Row zero is the bottom, matching `Game`; this helper neither runs rules nor draws.
public struct RefillMapping: Equatable, Sendable {
    public enum Origin: Equatable, Sendable {
        /// The exact pre-clear cell. Its column always equals the destination column.
        case survivor(source: Cell)
        /// A genuinely new piece generated by the turn's ordinary refill.
        case refill
        /// Free dead-board recovery overwrote this destination after gravity/refill.
        /// This is a replacement even when its final color matches the displaced piece.
        case recovery
    }

    public struct Piece: Equatable, Sendable {
        public let destination: Cell
        public let jewel: Jewel
        public let origin: Origin
    }

    /// All 49 final destinations, ordered by column, then bottom-to-top row.
    public let pieces: [Piece]

    /// Supply the `Turn` and final `Game` from the same successful `Game.tap`.
    /// No random generator, board mutation, color matching or persisted IDs are needed.
    public init(turn: Turn, settled: Game) {
        var pieces: [Piece] = []
        pieces.reserveCapacity(Game.side * Game.side)
        for column in 0..<Game.side {
            let survivingRows = (0..<Game.side).filter {
                !turn.cleared.contains(Cell($0, column))
            }
            for row in 0..<Game.side {
                let destination = Cell(row, column)
                let origin: Origin
                // Game.ensureMove replaces exactly these three cells, not the board.
                if turn.reshuffled && row == 0 && column < 3 {
                    origin = .recovery
                } else if row < survivingRows.count {
                    origin = .survivor(source: Cell(survivingRows[row], column))
                } else {
                    origin = .refill
                }
                pieces.append(Piece(destination: destination,
                                    jewel: settled.board[row * Game.side + column],
                                    origin: origin))
            }
        }
        self.pieces = pieces
    }
}
